// Generates the docs that must not drift from source: docs/accessibility/quirks.md (from the
// quirks registry and the code that checks each entry), the "Tested with" tables in docs
// pages (from docs/accessibility/tested-with.json) and llms.txt (from the guide pages).
// Run: pnpm docs:gen   ·   pnpm docs:check fails when a generated file is out of date.
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs"
import { join, relative } from "node:path"
import type { ComponentMeta } from "../packages/core/src/components/meta.ts"
import { quirks } from "../packages/core/src/dom/quirks.ts"

const repo = join(import.meta.dirname, "..")

interface QuirkEntry {
  readonly id: string
  readonly links: readonly string[]
  readonly test: string
  readonly removeWhen: string
  readonly verified: string
  readonly invariants?: readonly string[]
}

/** One manual screen-reader pass (docs/accessibility/tested-with.json). */
export interface TestedWith {
  readonly component: string
  readonly at: string
  readonly atVersion: string
  readonly browser: string
  readonly browserVersion: string
  readonly os: string
  /** YYYY-MM-DD */
  readonly date: string
  readonly result: "pass" | "issues"
  readonly notes?: string
}

/** quirks.md: the registry, plus where each entry is checked (`usedIn`: id → files). */
export function renderQuirks(
  entries: readonly QuirkEntry[],
  usedIn: Readonly<Record<string, readonly string[]>>,
): string {
  const rows = entries.map((q) => {
    const files = usedIn[q.id] ?? []
    return [
      `## \`${q.id}\``,
      "",
      `- Bugs: ${q.links.map((l) => `<${l}>`).join(", ")}`,
      `- Repro test: \`${q.test}\``,
      `- Checked in: ${files.length ? files.map((f) => `\`${f}\``).join(", ") : "component code (none yet)"}`,
      ...(q.invariants?.length
        ? [`- Allowed contract exceptions: ${q.invariants.map((i) => `\`${i}\``).join(", ")}`]
        : []),
      `- Last verified: ${q.verified}`,
      `- Remove when: ${q.removeWhen}`,
      "",
    ].join("\n")
  })
  const byFile = new Map<string, string[]>()
  for (const [id, files] of Object.entries(usedIn)) {
    for (const f of files) byFile.set(f, [...(byFile.get(f) ?? []), id])
  }
  return [
    "<!-- Generated by scripts/docs-gen.ts from packages/core/src/dom/quirks.ts. Do not edit. -->",
    "",
    "# Browser and assistive-technology quirks",
    "",
    "Every workaround rind-ui applies for one browser, platform or screen reader. Code checks",
    "an entry by id (`quirkActive`), never the user agent; each entry has a test reproducing",
    "the problem and is re-verified yearly (`pnpm quirks:check`).",
    "",
    "## By module",
    "",
    "| Module | Quirks |",
    "|---|---|",
    ...[...byFile.entries()]
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([f, ids]) => `| \`${f}\` | ${ids.map((i) => `\`${i}\``).join(", ")} |`),
    "",
    ...rows,
  ].join("\n")
}

/** The "Tested with" table of one component, newest pass first. */
export function renderTestedWith(records: readonly TestedWith[], component: string): string {
  const own = records
    .filter((r) => r.component === component)
    .sort((a, b) => b.date.localeCompare(a.date))
  if (own.length === 0) return "_No manual screen-reader pass recorded yet._"
  return [
    "| Screen reader | Browser | OS | Date | Result |",
    "|---|---|---|---|---|",
    ...own.map(
      (r) =>
        `| ${r.at} ${r.atVersion} | ${r.browser} ${r.browserVersion} | ${r.os} | ${r.date} | ${r.result}${r.notes ? ` — ${r.notes}` : ""} |`,
    ),
  ].join("\n")
}

/** Offset ranges of fenced code blocks and inline code spans: markers there are examples. */
function codeRanges(page: string): (readonly [number, number])[] {
  const ranges: (readonly [number, number])[] = []
  for (const m of page.matchAll(/^(```|~~~)[^\n]*\n[\s\S]*?^\1[^\n]*$/gm)) {
    ranges.push([m.index, m.index + m[0].length])
  }
  // Fences masked first, so their backticks never pair with an inline span's.
  let masked = page
  for (const [a, b] of ranges) masked = masked.slice(0, a) + " ".repeat(b - a) + masked.slice(b)
  for (const m of masked.matchAll(/`[^`]+`/g)) ranges.push([m.index, m.index + m[0].length])
  return ranges
}

/**
 * Replaces each `<!-- <kind>:<id> -->…<!-- /<kind> -->` block with `render(id)`, except
 * markers inside code (documentation showing the syntax).
 */
export function fillBlocks(page: string, kind: string, render: (id: string) => string): string {
  const ranges = codeRanges(page)
  const block = new RegExp(`(<!-- ${kind}:([\\w-]+) -->)[\\s\\S]*?(<!-- /${kind} -->)`, "g")
  return page.replace(
    block,
    (whole: string, open: string, id: string, close: string, offset: number) =>
      ranges.some(([a, b]) => offset >= a && offset < b)
        ? whole
        : `${open}\n${render(id)}\n${close}`,
  )
}

/** Fills `<!-- tested-with:<component> -->` blocks with the component's table. */
export const fillTestedWith = (page: string, records: readonly TestedWith[]): string =>
  fillBlocks(page, "tested-with", (component) => renderTestedWith(records, component))

/** The ARIA snapshot of a state story (written by the Playwright snapshot test). */
export function renderAria(storyId: string, read: (id: string) => string | undefined): string {
  const yaml = read(storyId)
  if (yaml === undefined) {
    throw new Error(
      `no ARIA snapshot for story ${storyId}: run the Playwright snapshot test with RIND_UPDATE_ARIA=1`,
    )
  }
  return ["```yaml", yaml.trimEnd(), "```"].join("\n")
}

const cell = (text: string) => text.replace(/\|/g, "\\|")
const table = (head: readonly string[], rows: readonly (readonly string[])[]) =>
  [
    `| ${head.join(" | ")} |`,
    `|${head.map(() => "---").join("|")}|`,
    ...rows.map((r) => `| ${r.map(cell).join(" | ")} |`),
  ].join("\n")

/** A component's API facts, from its `<scope>.meta.ts`. */
export function renderApi(meta: ComponentMeta): string {
  const { actions, queries, traits } = meta.contract
  return [
    "### Anatomy",
    "",
    table(
      ["Part", "`data-part`", "Element", ""],
      meta.parts.map((p) => [
        `\`${p.name}\``,
        `\`${p.part}\``,
        `\`<${p.element}>\``,
        p.description,
      ]),
    ),
    "",
    "### Props",
    "",
    table(
      ["Prop", "Type", "Default", ""],
      Object.entries(meta.props).map(([name, p]) => [
        `\`${name}\``,
        `\`${p.type}\``,
        p.default === undefined ? "—" : `\`${p.default}\``,
        p.description,
      ]),
    ),
    "",
    "Every attribute of the rendered element is accepted and forwarded.",
    "",
    "### Data attributes",
    "",
    table(
      ["Part", "Attribute", ""],
      Object.entries(meta.dataAttributes).flatMap(([part, attrs]) =>
        Object.entries(attrs).map(([attr, when]) => [`\`${part}\``, `\`${attr}\``, when]),
      ),
    ),
    "",
    "### Keyboard",
    "",
    table(
      ["Key", ""],
      meta.keyboard.map(([key, what]) => [key, what]),
    ),
    "",
    ...(meta.stateless
      ? ["### States", "", "None: the component is stateless (no machine, no `testMachine`).", ""]
      : []),
    "### Contract",
    "",
    table(
      ["Action", "Modalities"],
      Object.entries(actions).map(([name, m]) => [`\`${name}\``, m.join(", ")]),
    ),
    "",
    `Queries: ${queries.map((q) => `\`${q}\``).join(", ")}. Traits: ${
      traits.length ? traits.map((t) => `\`${t}\``).join(", ") : "none"
    }.`,
  ].join("\n")
}

/** Every component's meta: `packages/core/src/components/<scope>/<scope>.meta.ts`. */
async function loadMetas(): Promise<Map<string, ComponentMeta>> {
  const dir = join(repo, "packages/core/src/components")
  const out = new Map<string, ComponentMeta>()
  for (const scope of readdirSync(dir)) {
    const file = join(dir, scope, `${scope}.meta.ts`)
    if (!existsSync(file)) continue
    const mod = (await import(file)) as Record<string, ComponentMeta>
    const meta = Object.values(mod).find((v) => v.scope === scope)
    if (meta) out.set(scope, meta)
  }
  return out
}

/** llms.txt: one line per guide, from its `# Title` and first paragraph. */
type Page = { readonly path: string; readonly markdown: string }

/** One `- [Title](path): summary` line, from the page's `# Title` and first paragraph. */
function indexLine({ path, markdown }: Page): string {
  const title = /^# (.+)$/m.exec(markdown)?.[1] ?? path
  const summary =
    markdown
      .split(/\n\s*\n/)
      .map((p) => p.trim())
      .find((p) => p && !p.startsWith("#") && !p.startsWith("<!--"))
      ?.replace(/\s+/g, " ") ?? ""
  return `- [${title}](${path}): ${summary}`
}

export function renderLlms(guides: readonly Page[], components: readonly Page[] = []): string {
  const lines = guides.map(indexLine)
  return [
    "# rind-ui",
    "",
    "> Headless React components: behaviour, accessibility and state, styled through data-* attributes.",
    "",
    "## Guides",
    "",
    ...lines,
    "",
    ...(components.length ? ["## Components", "", ...components.map(indexLine), ""] : []),
    "## Accessibility",
    "",
    "- [Support matrix](docs/accessibility/support-matrix.md): which screen reader and browser combinations are supported, and how each is tested.",
    "- [Quirks](docs/accessibility/quirks.md): every browser and assistive-technology workaround, with its bug links.",
    "",
  ].join("\n")
}

const markdownFiles = (dir: string): string[] =>
  existsSync(dir)
    ? readdirSync(dir, { recursive: true, encoding: "utf8" })
        .filter((f) => f.endsWith(".md"))
        .map((f) => join(dir, f))
        .sort()
    : []

/** id → source files (outside tests) that call quirkActive with it. */
function quirkUsage(): Record<string, string[]> {
  const usage: Record<string, string[]> = {}
  for (const pkg of readdirSync(join(repo, "packages"))) {
    const src = join(repo, "packages", pkg, "src")
    if (!existsSync(src)) continue
    for (const f of readdirSync(src, { recursive: true, encoding: "utf8" })) {
      if (!/\.tsx?$/.test(f) || /\.test(-d)?\.tsx?$/.test(f) || f.endsWith("quirks.ts")) continue
      const file = join(src, f)
      for (const [, id] of readFileSync(file, "utf8").matchAll(/quirkActive\("([\w-]+)"/g)) {
        if (!id) continue
        const rel = relative(repo, file)
        usage[id] = [...new Set([...(usage[id] ?? []), rel])]
      }
    }
  }
  return usage
}

const ariaDir = join(repo, "apps/storybook/stories/__aria__")
const readAria = (id: string) => {
  const file = join(ariaDir, `${id}.aria.yml`)
  return existsSync(file) ? readFileSync(file, "utf8") : undefined
}

/** Every generated file: path → expected content. */
export async function generate(): Promise<Map<string, string>> {
  const metas = await loadMetas()
  const out = new Map<string, string>()
  out.set("docs/accessibility/quirks.md", renderQuirks(quirks, quirkUsage()))
  const records = JSON.parse(
    readFileSync(join(repo, "docs/accessibility/tested-with.json"), "utf8"),
  ) as { records: TestedWith[] }
  for (const file of markdownFiles(join(repo, "docs"))) {
    const page = readFileSync(file, "utf8")
    const filled = fillBlocks(
      fillBlocks(fillTestedWith(page, records.records), "aria", (id) => renderAria(id, readAria)),
      "api",
      (scope) => {
        const meta = metas.get(scope)
        if (!meta) throw new Error(`no ${scope}.meta.ts for the api block in ${file}`)
        return renderApi(meta)
      },
    )
    if (filled !== page) out.set(relative(repo, file), filled)
  }
  // The theme pages are guides too (tokens.md is generated by scripts/theme-docs.mjs).
  const themePages = ["white-label", "builder", "tokens"].map((n) =>
    join(repo, `docs/theme/${n}.md`),
  )
  const guides = [...markdownFiles(join(repo, "docs/guides")), ...themePages].map((file) => ({
    path: relative(repo, file),
    markdown: readFileSync(file, "utf8"),
  }))
  const components = markdownFiles(join(repo, "docs/components")).map((file) => ({
    path: relative(repo, file),
    markdown: readFileSync(file, "utf8"),
  }))
  out.set("llms.txt", renderLlms(guides, components))
  return out
}

if (import.meta.main) {
  const check = process.argv.includes("--check")
  const stale: string[] = []
  for (const [path, content] of await generate()) {
    const file = join(repo, path)
    const current = existsSync(file) ? readFileSync(file, "utf8") : ""
    if (current === content) continue
    if (check) stale.push(path)
    else writeFileSync(file, content)
  }
  if (stale.length > 0) {
    console.error(`out of date (run pnpm docs:gen): ${stale.join(", ")}`)
    process.exit(1)
  }
}
